"export function ControlPanel({ onLog, selectedPod, k8sNodes, k8sPods, operatorStatus, k8sApi, onOpenLogs }: ControlPanelProps) {
  const [selectedNodeForPodConn, setSelectedNodeForPodConn] = useState<string>('');
  const [iptablesDropped, setIptablesDropped] = useState<boolean>(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const selectedPodObj = k8sPods.find(p => p.name === selectedPod);

  const defaultWorkerNode = k8sNodes.find(n => !n.name.includes('control-plane'))?.name || k8sNodes[0]?.name || '';
  const targetNode = selectedPodObj?.nodeName || selectedNodeForPodConn || defaultWorkerNode;

  // Real-time kernel iptables status polling
  useEffect(() => {
    if (!targetNode || !k8sApi.getIptablesStatus) return;
    let isMounted = true;
    const check = async () => {
      try {
        const res = await k8sApi.getIptablesStatus(targetNode);
        if (isMounted && typeof res.dropped === 'boolean') {
          setIptablesDropped(res.dropped);
        }
      } catch {
        // ignore polling errors
      }
    };
    check();
    const interval = setInterval(check, 3000);
    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, [targetNode, k8sApi]);
"

